# icons offered in the admin icon picker (content icons)
PICKER = [
    "code", "messages", "server", "globe", "wrench", "shield", "shield-check", "zap", "headphones",
    "trending-up", "layers", "tag", "cloud", "upload-cloud", "lock", "database", "gauge", "sliders",
    "rocket", "users", "layout", "cart", "hard-drive", "refresh", "monitor", "smartphone", "heart",
    "star", "cpu", "briefcase", "clock", "award", "search", "mail", "check",
]


def icon(name, cls="ic", size=None):
    inner = ICONS.get(name) or ICONS["check"]
    sz = f' width="{size}" height="{size}"' if size else ""
    return Markup(
        f'<svg class="{cls}"{sz} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" '
        f'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{inner}</svg>'
    )
